# ── 3b: Helper — seed control & case locator ─────────────────────────────────
def set_all_seeds(seed):
    random.seed(seed)
    np.random.seed(seed)
    if HYPATIA_AVAILABLE:
        torch.manual_seed(seed)
        try:
            torch.use_deterministic_algorithms(True)
        except Exception as _e:
            import logging as _lg, os as _os
            _lg.getLogger(__name__).warning('swallowed: %r', _e)
            if _os.environ.get('HYPATIAX_STRICT') == '1': raise


def _iter_protocol_cases(proto):
    """Normalize protocol cases across legacy and modern DeFi APIs.

    The older audit code expects `proto.get_cases()` and
    `proto.build_train_test_split(...)`. The current repository exposes
    `load_test_data()` / `get_all_domains()` instead. We translate the latter
    into the legacy shape that the notebook code expects.
    """
    domains = []
    if hasattr(proto, 'get_all_domains'):
        try:
            domains = list(proto.get_all_domains())
        except Exception:
            domains = []
    if not domains and hasattr(proto, 'domains'):
        domains = list(getattr(proto, 'domains').keys())

    records = []
    for domain in domains:
        try:
            rows = proto.load_test_data(domain, num_samples=200)
        except Exception:
            continue
        for idx, row in enumerate(rows):
            if not isinstance(row, tuple) or len(row) != 5:
                continue
            description, X, y, variables, metadata = row
            records.append({
                'name': description,
                'description': description,
                'domain': domain,
                'index': idx,
                'X': np.asarray(X),
                'y': np.asarray(y),
                'variables': list(variables),
                'metadata': dict(metadata or {}),
            })
    return records


def _split_case_data(X, y, feature_names=None, return_metadata=False):
    """Return the legacy split by default, or an explicit audited PCA split."""
    X = np.asarray(X)
    y = np.asarray(y)
    if X.ndim == 1:
        X = X.reshape(-1, 1)

    if len(X) == 0:
        raise RuntimeError('Empty case data encountered while creating train/test split.')

    if PCA_PORTFOLIO_SWEEP:
        from hypatiax.tools.utils.pca_split_utils import pca_directed_split
        X_train, X_test, y_train, y_test, metadata = pca_directed_split(
            X, y, test_size=0.6, random_state=42,
            feature_names=feature_names, return_metadata=True
        )
        return (X_train, y_train, X_test, y_test, metadata) if return_metadata else (
            X_train, y_train, X_test, y_test
        )

    from hypatiax.tools.utils.pca_split_utils import first_feature_percentile_split
    return first_feature_percentile_split(X, y, return_metadata=return_metadata)


def find_portfolio_variance_case(proto):
    """Return the explicitly designated Portfolio VaR protocol case.

    The audit title historically says Portfolio Variance, but the actual
    protocol case is Portfolio VaR for two correlated assets. Exact identity
    prevents domain-order changes from silently selecting a different case.
    """
    from hypatiax.tools.utils.pca_split_utils import select_case_by_identity

    case_rows = _iter_protocol_cases(proto)
    if not case_rows:
        raise RuntimeError('Portfolio VaR case not found: protocol catalogue is empty.')
    try:
        return select_case_by_identity(
            case_rows, domain='risk_var',
            name='Portfolio VaR for two correlated assets'
        )
    except ValueError as exc:
        raise RuntimeError(
            'Expected exactly one risk_var case named '
            '"Portfolio VaR for two correlated assets"; verify the protocol catalogue.'
        ) from exc


